/*
 d = b - c
                e = a_d 
                where
                a  ∈ ℝ^3
                b  ∈ ℤ index
                c  ∈ ℤ index
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    int d;
    DT e;

    heartlib(
        const Eigen::Matrix<double, 3, 1> & a,
        const int & b,
        const int & c)
    {

        // d = b - c
        d = b - c;
        // e = a_d
        e = a[d-1];
    }
};

