function output = heartlib(a, b, c)
% output = heartlib(a, b, c)
%
%     d = b - c
%                    e = a_d 
%                    where
%                    a  ∈ ℝ^3
%                    b  ∈ ℤ index
%                    c  ∈ ℤ index
    a = reshape(a,[],1);

    assert( numel(a) == 3 );
    assert(numel(b) == 1);
    assert(numel(c) == 1);

    % d = b - c

    d = b - c;
    % e = a_d

    e = a(d);
    output.d = d;
    output.e = e;
end

